/* Export using the supplied ministry DOCX, preserving its styles, tables and page setup. */
(() => {
  const W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
  const XML = 'http://www.w3.org/XML/1998/namespace';
  const TEMPLATE = '';
  const children = (el, name) => [...el.children].filter(x => x.namespaceURI === W && x.localName === name);
  const descendants = (el, name) => [...el.getElementsByTagNameNS(W, name)];
  const rows = id => [...document.querySelectorAll('#'+id+' tr:not(.empty-row)')].map(row => ({...row.dataset}));
  const value = name => {
    const input = document.querySelector('#editGeneral [name="'+name+'"]');
    if (input?.type === 'radio') return document.querySelector('#editGeneral [name="'+name+'"]:checked')?.value ?? '';
    return input?.value || '';
  };
  const date = raw => /^\d{4}-\d{2}-\d{2}$/.test(raw || '') ? raw.split('-').reverse().join('/') : (raw || '');
  const year = raw => /^\d{4}-/.test(raw || '') ? raw.slice(0,4) : (raw || '');
  function setParagraph(p, text) {
    const run = children(p,'r')[0];
    const style = run && children(run,'rPr')[0]?.cloneNode(true);
    [...p.children].filter(x => x.localName !== 'pPr').forEach(x=>x.remove());
    String(text).split(/([\t\n])/).forEach(part => {
      const r=p.ownerDocument.createElementNS(W,'w:r');
      if (style) r.appendChild(style.cloneNode(true));
      const t=p.ownerDocument.createElementNS(W,part==='\t'?'w:tab':part==='\n'?'w:br':'w:t');
      if (part!=='\t' && part!=='\n') { t.setAttributeNS(XML,'xml:space','preserve'); t.textContent=part; }
      r.appendChild(t); p.appendChild(r);
    });
  }
  function setCell(cell,text) {
    const ps=children(cell,'p');
    const p=ps[0] || cell.appendChild(cell.ownerDocument.createElementNS(W,'w:p'));
    ps.slice(1).forEach(x=>x.remove()); setParagraph(p,text);
  }
  function setRows(table, data) {
    const old=children(table,'tr'), seed=old[1];
    old.slice(1).forEach(x=>x.remove());
    const count=Math.max(data.length,old.length-1);
    for (let i=0;i<count;i++) {
      const row=seed.cloneNode(true);
      children(row,'tc').forEach((cell,j)=>setCell(cell,data[i]?.[j] ?? ''));
      table.appendChild(row);
    }
  }
  async function build(variant = "standard") {
    if(!["standard","textbooks","awards","full"].includes(variant)) throw new Error("Mẫu xuất không hợp lệ.");
    const zip=await JSZip.loadAsync(TEMPLATE,{base64:true});
    const xml=await zip.file('word/document.xml').async('string');
    const doc=new DOMParser().parseFromString(xml,'application/xml');
    if (doc.getElementsByTagName('parsererror').length) throw new Error('Mẫu Word không hợp lệ.');
    const body=doc.getElementsByTagNameNS(W,'body')[0];
    const p=children(body,'p'), tables=children(body,'tbl');
    const education=rows('credentialBody'), degrees=education.filter(x=>x.kind==='degree'&&x.unfinished!=='1');
    const rank=x=>/tiến sĩ/i.test(x.level)?3:/thạc sĩ/i.test(x.level)?2:1;
    const highest=[...degrees].sort((a,b)=>rank(b)-rank(a)||Number(b.year)-Number(a.year))[0] || {};
    const titles=education.filter(x=>x.kind==='title');
    const title=[...titles].sort((a,b)=>(/phó/i.test(a.level)?0:1)-(/phó/i.test(b.level)?0:1)||Number(a.year)-Number(b.year)).pop() || {};
    const under=degrees.filter(x=>rank(x)===1), first=under[0] || {}, second=under[1] || {};
    const master=degrees.find(x=>rank(x)===2) || {}, doctor=degrees.find(x=>rank(x)===3) || {};
    const replacements={
      7:'Họ và tên: '+value('person_name')+'\tGiới tính: '+({0:'Nữ',1:'Nam'}[value('person_gender')] || ''),
      8:'Ngày, tháng, năm sinh: '+date(value('person_dob'))+'\t Nơi sinh: '+value('person_pob'),
      9:'Quê quán: '+value('person_hometown')+'\tDân tộc: '+value('person_ethnicity'),
      10:'Học vị cao nhất: '+(highest.level||'')+'\tNăm, nước nhận học vị: '+[highest.year,highest.country].filter(Boolean).join(', '),
      11:'Chức danh khoa học cao nhất: '+(title.level||'')+'\tNăm bổ nhiệm: '+(title.year||''),
      12:'Chức vụ (hiện tại hoặc trước khi nghỉ hưu): '+value('person_position'),
      13:'Đơn vị công tác (hiện tại hoặc trước khi nghỉ hưu): '+value('person_work_unit'),
      14:'Chỗ ở riêng hoặc địa chỉ liên lạc: '+value('person_address'),
      15:'Điện thoại liên hệ:  CQ: '+value('person_office_phone')+'\tNR: '+value('person_home_phone')+'\tDĐ: '+value('person_mobile_phone'),
      16:'Fax: '+value('person_fax')+'\tE-mail: '+value('person_email'),
      17:'Số CMND: '+value('person_citizen_id')+'\tNgày cấp: '+date(value('person_date_issue'))+'\tNơi cấp: '+value('person_place_issue'),
      20:'Hệ đào tạo: '+(first.trainingSystem||''),21:'Nơi đào tạo: '+(first.institution||''),22:'Ngành học: '+(first.major||''),
      23:'Nước đào tạo: '+(first.country||'')+'\tNăm tốt nghiệp: '+(first.year||''),
      24:'Bằng đại học 2: '+[second.level,second.major].filter(Boolean).join(' – ')+'\tNăm tốt nghiệp: '+(second.year||''),
      26:'Thạc sĩ chuyên ngành: '+(master.major||'')+'\tNăm cấp bằng: '+(master.year||''),27:'Nơi đào tạo: '+(master.institution||''),
      28:'Tiến sĩ chuyên ngành: '+(doctor.major||'')+'\tNăm cấp bằng: '+(doctor.year||''),29:'Nơi đào tạo: '+(doctor.institution||''),30:'Tên luận án: '+(doctor.thesis||'')
    };
    Object.entries(replacements).forEach(([i,text])=>setParagraph(p[Number(i)],text));
    const language=rows('languageBody');
    const languageCells=children(children(tables[0],'tr')[0],'tc');
    setCell(languageCells[1],language.length?language.map((x,i)=>(i+1)+'. '+x.name).join('\n'):'1. …………………………\n2. …………………………\n3. …………………………');
    setCell(languageCells[2],language.length?language.map(x=>'Mức độ sử dụng: '+[x.proficiency,x.certificate].filter(Boolean).join(' – ')).join('\n'):'Mức độ sử dụng: ………………………\nMức độ sử dụng: ………………………\nMức độ sử dụng: ………………………');
    setRows(tables[1],rows('workBody').map(x=>[date(x.start)+' – '+(x.current==='1'?'Hiện tại':date(x.end)),x.institution,[x.position,x.description].filter(Boolean).join('\n')]));
    setRows(tables[2],rows('projectBody').map((x,i)=>[i+1,x.title,year(x.startYear)+' / '+year(x.endYear),x.level,x.position]));
    const works=[...rows('articleBody').map(x=>[x.title,x.year,x.journal]),...rows('seminarBody').map(x=>[x.title,x.year,x.publisher])];
    setRows(tables[3],works.map((x,i)=>[i+1,...x]));
    const addSection = (heading, paragraphSeed, headers, data) => {
      const label=paragraphSeed.cloneNode(true);setParagraph(label,heading);
      const table=tables[3].cloneNode(true);
      children(children(table,'tr')[0],'tc').forEach((cell,i)=>setCell(cell,headers[i]));
      setRows(table,data);
      // Keep heading and first row together and repeat the table header on later pages.
      const pr=children(label,'pPr')[0] || label.insertBefore(doc.createElementNS(W,'w:pPr'),label.firstChild);
      if(!children(pr,'keepNext').length) pr.appendChild(doc.createElementNS(W,'w:keepNext'));
      const header=children(table,'tr')[0];
      const trpr=children(header,'trPr')[0] || header.insertBefore(doc.createElementNS(W,'w:trPr'),header.firstChild);
      if(!children(trpr,'tblHeader').length) trpr.appendChild(doc.createElementNS(W,'w:tblHeader'));
      body.insertBefore(label,p[41]);body.insertBefore(table,p[41]);
    };
    if(variant==='textbooks'||variant==='full') addSection('3. Sách và giáo trình đã biên soạn:',p[39],
      ['TT','Tên sách / giáo trình','Năm xuất bản','Nhà xuất bản'],
      rows('textbookBody').map((x,i)=>[i+1,[x.title,x.description].filter(Boolean).join('\n'),x.year,[x.publisher,x.month?'Tháng '+x.month:''].filter(Boolean).join('\n')]));
    if(variant==='awards'||variant==='full') addSection('V. GIẢI THƯỞNG VÀ THÀNH TÍCH',p[36],
      ['TT','Giải thưởng / Thành tích','Năm','Nơi cấp / Áp dụng'],
      rows('awardBody').map((x,i)=>[i+1,[x.category,x.name,x.description].filter(Boolean).join('\n'),x.year,x.organization]));
    const signature=children(children(tables[4],'tr')[0],'tc')[1];
    setCell(signature,'Người khai ký tên\n(Ghi rõ chức danh, học vị)\n\n\n'+value('person_name'));
    if(variant!=='standard') {
      const datePr=children(p[41],'pPr')[0] || p[41].insertBefore(doc.createElementNS(W,'w:pPr'),p[41].firstChild);
      if(!children(datePr,'keepNext').length) datePr.appendChild(doc.createElementNS(W,'w:keepNext'));
      const signRow=children(tables[4],'tr')[0];
      const signPr=children(signRow,'trPr')[0] || signRow.insertBefore(doc.createElementNS(W,'w:trPr'),signRow.firstChild);
      if(!children(signPr,'cantSplit').length) signPr.appendChild(doc.createElementNS(W,'w:cantSplit'));
    }
    zip.file('word/document.xml',new XMLSerializer().serializeToString(doc));
    return {zip,body};
  }
  const escape=text=>String(text).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
  function previewParagraph(p) {
    const jc=descendants(p,'jc')[0]?.getAttributeNS(W,'val')||'left';
    const size=Number(descendants(p,'sz')[0]?.getAttributeNS(W,'val')||26)/2;
    const text=descendants(p,'r').map(r=>children(r,'t').map(t=>escape(t.textContent)).join('')+(children(r,'tab').length?'&emsp;':'')+(children(r,'br').length?'<br>':'')).join('');
    return '<p style="text-align:'+jc+';font-size:'+size+'pt;margin:0 0 5pt">'+(text||'&nbsp;')+'</p>';
  }
  window.MinistryExport={
    create:async(variant="standard")=>{const {zip}=await build(variant);return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});},
    preview:async(variant="standard")=>{const {body}=await build(variant);return '<div style="font-family:Times New Roman;color:#000">'+[...body.children].map(el=>{
      if(el.localName==='p')return previewParagraph(el);
      if(el.localName!=='tbl')return '';
      const grid=descendants(el,'gridCol').map(x=>Number(x.getAttributeNS(W,'w'))),sum=grid.reduce((a,b)=>a+b,0);
      return '<table style="width:100%;border-collapse:collapse;margin:5pt 0">'+children(el,'tr').map(row=>'<tr>'+children(row,'tc').map((cell,i)=>'<td style="border:1px solid #000;padding:3pt;width:'+((grid[i]||sum/grid.length)/sum*100)+'%">'+children(cell,'p').map(previewParagraph).join('')+'</td>').join('')+'</tr>').join('')+'</table>';
    }).join('')+'</div>';}
  };
})();
